"""Real PostgreSQL finance workflow tests. Fictional records; no live payments."""
from support import Client,sql
import uuid,json,pathlib,datetime,concurrent.futures,subprocess
results=[];tag=uuid.uuid4().hex[:8];today=datetime.date.today();date=today.isoformat();start=f'{today.year}-01-01';end=f'{today.year}-12-31'
def check(name,ok,data=None):
 results.append({'test':name,'passed':bool(ok)});pathlib.Path('test-results/phase7.json').write_text(json.dumps(results,indent=2));print(('PASS ' if ok else 'FAIL ')+name,flush=True);assert ok,(name,data)
def good(c,p,m='GET',d=None):
 code,b=c.req(p,m,d);assert code in (200,204),(p,code,b);return b
def login(email,role,org=None):
 c=Client();assert c.login(email)[0]==200;ws=good(c,'/workspaces');w=next(w for w in ws if w['role']==role and (not org or w['orgId']==org) and (role!='Association Super Admin' or w['association'].startswith('Global')));c.activate(w);return c,w
admin,w=login('admin@example.test','Association Super Admin');review,rw=login('secretary@example.test','Association Super Admin',w['orgId']);club=sql('SELECT "Id" FROM "Orgs" WHERE "Code"=\'GC-006\'');member,mw=login('member@example.test','Club Member',club)
pid=sql('SELECT "Id" FROM "Persons" WHERE "UserId"=(SELECT "Id" FROM "Users" WHERE "Email"=\'member@example.test\')');mid=sql(f'SELECT "Id" FROM "Memberships" WHERE "PersonId"=\'{pid}\' AND "ClubId"=\'{club}\' AND "Status"=\'Active\' LIMIT 1');reviewid=sql('SELECT "Id" FROM "Users" WHERE "Email"=\'secretary@example.test\'')
def entity(name):
 e=good(admin,'/finance/entities','POST',{'orgId':club,'name':name+' '+tag,'country':'US','currency':'USD','decimals':2,'collectionAuthority':'Fictional QA independent club collection'});p='/finance/entities/'+e['id'];good(admin,p+'/periods','POST',{'name':'Fiscal year','startsOn':start,'endsOn':end});good(admin,p+'/grants','POST',{'userId':reviewid,'role':'Owner'});return e,p
e,p=entity('Club fund');check('entity separate from organization',e['id']!=club);check('double-entry chart initialized',len(good(admin,p+'/accounts'))>=18);check('entity access requires explicit grant',member.req(p+'/dashboard')[0]==403)
def invoice(amount='100.00',key=None,lines=None):
 return good(admin,p+'/invoices','POST',{'personId':pid,'customer':'Fictional member','purpose':'ClubDues','date':date,'dueOn':date,'key':key or uuid.uuid4().hex,'lines':lines or [{'description':'Annual membership','quantity':'1','rate':amount}]})
i=invoice(lines=[{'description':'Taxable fee','quantity':'2','rate':'50','discount':'10','taxPercent':'10'}]);check('decimal invoice math',i['subtotal']==90 and i['tax']==9 and i['total']==99,i)
check('extra currency decimals rejected',admin.req(p+'/invoices','POST',{'customer':'Bad','purpose':'Other','date':date,'dueOn':date,'key':uuid.uuid4().hex,'lines':[{'description':'Wrong precision','quantity':1,'rate':'1.001'}]})[0]==400)
i=good(admin,'/finance/invoices/'+i['id']+'/issue','POST',{});check('number assigned on issuance',i['number'].startswith('INV-'));check('issued invoice unpaid',i['outstanding']==99 and i['paid']==0)
check('member own invoice readable',good(member,'/finance/invoices/'+i['id'])['invoice']['id']==i['id']);check('member self portal accurate',any(x['id']==i['id'] for x in good(member,'/my/finance')['invoices']))
check('member cannot issue credit',member.req('/finance/invoices/'+i['id']+'/credits','POST',{'amount':1,'reason':'no','key':uuid.uuid4().hex})[0]==403)
check('provider not configured denies checkout',member.req('/finance/invoices/'+i['id']+'/payment-intents','POST',{'key':uuid.uuid4().hex})[0]==409)
check('issued invoice cannot cancel',admin.req('/finance/invoices/'+i['id']+'/cancel','POST',{'reason':'No edit'})[0]==409)
check('invoice PDF real',member.request('/finance/invoices/'+i['id']+'/pdf')[1].startswith(b'%PDF'))
def payment(amount,ref=None):
 return good(admin,p+'/payments','POST',{'personId':pid,'payer':'Fictional member','reference':ref or uuid.uuid4().hex,'method':'BankTransfer','currency':'USD','amount':amount,'date':date,'key':uuid.uuid4().hex,'evidence':'Fictional bank evidence'})
pa=payment('120');check('manual payment is pending',pa['status']=='Pending' and pa['receiptNumber']=='');check('unverified receipt denied',member.request('/finance/payments/'+pa['id']+'/receipt')[0]==409);check('self verification denied',admin.req('/finance/payments/'+pa['id']+'/verify','POST',{})[0]==403)
pa=good(review,'/finance/payments/'+pa['id']+'/verify','POST',{});check('independent verification creates receipt',pa['status']=='Verified' and pa['receiptNumber'].startswith('REC-'))
alloc={'invoiceId':i['id'],'amount':'40','key':uuid.uuid4().hex};good(review,'/finance/payments/'+pa['id']+'/allocate','POST',alloc);good(review,'/finance/payments/'+pa['id']+'/allocate','POST',alloc);check('allocation retry idempotent',good(member,'/finance/invoices/'+i['id'])['invoice']['paid']==40)
check('partial payment separate balance',good(member,'/finance/invoices/'+i['id'])['invoice']['paymentStatus']=='Partially paid');good(review,'/finance/payments/'+pa['id']+'/allocate','POST',{'invoiceId':i['id'],'amount':'59','key':uuid.uuid4().hex});check('full payment balance zero',good(member,'/finance/invoices/'+i['id'])['invoice']['outstanding']==0);check('overpayment retained as unapplied',good(review,p+'/payments')[0 if len(good(review,p+'/payments'))==1 else next(n for n,x in enumerate(good(review,p+'/payments')) if x['id']==pa['id'])]['unallocated']==21)
check('over allocation rejected',review.req('/finance/payments/'+pa['id']+'/allocate','POST',{'invoiceId':i['id'],'amount':'1','key':uuid.uuid4().hex})[0]==409)
bank=good(admin,p+'/bank-accounts','POST',{'name':'Fictional bank','accountNumber':'1234567890','routingDetails':'TEST ONLY'});check('bank details protected',bank['maskedNumber'].endswith('7890') and 'protectedDetails' not in bank and '1234567890' not in json.dumps(bank))
good(review,'/finance/payments/'+pa['id']+'/settle','POST',{'bankAccountId':bank['id'],'date':date,'fee':'2','reference':'SETTLE-'+tag});check('cash bank only after settlement',good(admin,p+'/dashboard')['cashBank']==118)
rows={'bankAccountId':bank['id'],'rows':[{'date':date,'amount':'118','reference':'BANK-'+tag,'key':'BANK-'+tag}]};check('statement import',good(review,p+'/reconciliation/import','POST',rows)['imported']==1);check('duplicate statement import safe',good(review,p+'/reconciliation/import','POST',rows)['imported']==0);row=good(review,p+'/reconciliation')[0];good(review,'/finance/reconciliation/'+row['id']+'/match','POST',{'paymentId':pa['id']});check('statement matched without duplicate cash',good(admin,p+'/dashboard')['cashBank']==118)
good(review,'/finance/payments/'+pa['id']+'/refunds','POST',{'invoiceId':i['id'],'amount':'10','reason':'Completed refund','reference':'REF-'+tag});check('refund reopens invoice balance',good(member,'/finance/invoices/'+i['id'])['invoice']['outstanding']==10);credit=good(admin,'/finance/invoices/'+i['id']+'/credits','POST',{'amount':'10','reason':'Returned charge','key':'credit-'+tag});check('credit preserves issued total',good(member,'/finance/invoices/'+i['id'])['invoice']['total']==99);check('credit clears returned receivable',good(member,'/finance/invoices/'+i['id'])['invoice']['outstanding']==0)
good(review,'/finance/payments/'+pa['id']+'/refunds','POST',{'invoiceId':None,'amount':'1','kind':'Chargeback','reason':'Bank-confirmed unallocated debit','reference':'CB-'+tag});check('chargeback correction journal recorded',int(sql(f'SELECT count(*) FROM "FinanceJournals" WHERE "EntityId"=\'{e["id"]}\' AND "Source" LIKE \'refund:%\''))==2)
check('verified receipt generated from actual record',member.request('/finance/payments/'+pa['id']+'/receipt')[1].startswith(b'%PDF'))
check('unbalanced journal rejected',admin.req(p+'/journals','POST',{'date':date,'key':uuid.uuid4().hex,'narration':'Bad','lines':[{'account':'1010','debit':'10','credit':'0'},{'account':'3000','debit':'0','credit':'9'}]})[0]==400)
j=good(admin,p+'/journals','POST',{'date':date,'key':uuid.uuid4().hex,'narration':'Opening funds','lines':[{'account':'1010','debit':'10','credit':'0'},{'account':'3000','debit':'0','credit':'10'}]});good(admin,'/finance/journals/'+j['id']+'/reverse','POST',{'reason':'Reverse fictional opening'});check('journal reversal is separate entry',int(sql(f'SELECT count(*) FROM "FinanceJournals" WHERE "ReversesId"=\'{j["id"]}\''))==1)
def denied_sql(query):
 try:sql(query);return False
 except subprocess.CalledProcessError:return True
check('database blocks posted journal edit',denied_sql(f'UPDATE "FinanceJournals" SET "Narration"=\'tampered\' WHERE "Id"=\'{j["id"]}\''));check('database blocks issued invoice edit',denied_sql(f'UPDATE "FinanceInvoices" SET "Customer"=\'tampered\' WHERE "Id"=\'{i["id"]}\''))
period=good(admin,p+'/settings')['periods'][0];good(admin,p+'/periods/'+period['id']+'/close','POST',{'reason':'QA close'});check('closed period rejects posting',admin.req(p+'/journals','POST',{'date':date,'key':uuid.uuid4().hex,'narration':'Closed','lines':[{'account':'1010','debit':1,'credit':0},{'account':'3000','debit':0,'credit':1}]})[0]==409);good(admin,p+'/periods/'+period['id']+'/reopen','POST',{'reason':'QA reopen'});check('period reopen audited',any(x['action']=='period.reopen' for x in good(admin,p+'/audit')))
plan=good(admin,p+'/dues-plans','POST',{'name':'Annual '+tag,'billingOrgId':club,'purpose':'ClubDues','effectiveFrom':start,'effectiveTo':end,'components':[{'description':'Annual dues','amount':'75'}]});assessment={'membershipId':mid,'startsOn':start,'endsOn':f'{today.year+1}-01-01'};dues=good(admin,'/finance/dues-plans/'+plan['id']+'/assess','POST',assessment)['invoice'];again=good(admin,'/finance/dues-plans/'+plan['id']+'/assess','POST',assessment)['invoice'];check('annual dues generated',dues['total']==75);check('duplicate assessment returns same invoice',dues['id']==again['id'])
life=good(admin,p+'/dues-plans','POST',{'name':'Life '+tag,'billingOrgId':club,'purpose':'JoiningFee','effectiveFrom':start,'effectiveTo':f'{today.year+2}-12-31','once':True,'components':[{'description':'Life fee','amount':'500'}]});one=good(admin,'/finance/dues-plans/'+life['id']+'/assess','POST',assessment)['invoice'];two=good(admin,'/finance/dues-plans/'+life['id']+'/assess','POST',{**assessment,'startsOn':f'{today.year+1}-01-01','endsOn':f'{today.year+2}-01-01'})['invoice'];check('life joining fee bills once',one['id']==two['id'])
waiver=good(admin,p+'/dues-plans','POST',{'name':'Exemption '+tag,'billingOrgId':club,'purpose':'Other','effectiveFrom':start,'effectiveTo':end,'components':[{'description':'Special assessment','amount':'20'}]});check('fully approved waiver creates no fake invoice',good(admin,'/finance/dues-plans/'+waiver['id']+'/assess','POST',{**assessment,'discount':'20','reason':'Authorized fictional exemption'})['waived']);check('waiver retry cannot silently bill',admin.req('/finance/dues-plans/'+waiver['id']+'/assess','POST',assessment)[0]==409)
changed=good(admin,p+'/dues-plans','POST',{'name':'Revised annual '+tag,'billingOrgId':club,'purpose':'ClubDues','effectiveFrom':date,'effectiveTo':end,'components':[{'description':'New rate','amount':'90'}]});check('new schedule leaves historical invoice frozen',good(admin,'/finance/invoices/'+dues['id'])['invoice']['total']==75)
report=good(admin,p+'/reports/trial-balance');check('trial balance reconciles',report['trialDifference']==0);check('balance sheet reconciles',report['balanceSheetDifference']==0);check('income statement from posted records',good(admin,p+'/reports/income-statement')['income']>0);check('safe CSV export',admin.request(p+'/reports/trial-balance?format=csv')[0]==200);check('real report PDF',admin.request(p+'/reports/balance-sheet?format=pdf')[1].startswith(b'%PDF'));check('member denied entity reports',member.req(p+'/reports/trial-balance')[0]==403)
other=next(x for x in good(admin,'/workspaces') if x['tenantId']!=w['tenantId']);admin.activate(other);check('cross tenant invoice denied',admin.req('/finance/invoices/'+i['id'])[0]==404);admin.activate(w)
